fn count_digits(text: &Vec<char>) -> usize {
    let mut count = 0;
    for &c in text.iter() {
        // ASCII digits are '0' (0x30) through '9' (0x39)
        if c >= '0' && c <= '9' {
            count += 1;
        }
    }
    count
}

